"use client";

import Link from "next/link";
import { useEffect, useState } from "react";
import { Plus, Wrench, MapPin, CalendarCheck, Tag } from "lucide-react";
import { api, ApiError } from "@/lib/api-client";

type Service={id:string;title:string;description:string;price:number|null;price_type:string;location:string|null;service_area:string|null;booking_required:boolean;status:string;slug:string};

export default function VendorServicesPage(){
 const [services,setServices]=useState<Service[]>([]); const [loading,setLoading]=useState(true); const [error,setError]=useState("");
 async function load(){setLoading(true);setError("");try{const r=await api.get<{services:Service[]}>("/api/services/me");setServices(r.services);}catch(e){setError(e instanceof ApiError?e.message:"Unable to load services");}finally{setLoading(false);}}
 useEffect(()=>{void load()},[]);
 return <div className="shell py-8"><div className="flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"><div><p className="text-xs font-semibold uppercase tracking-[0.16em] text-ember-600">TTFL Services</p><h1 className="mt-1 text-2xl font-bold text-graphite-900 dark:text-white">Your services</h1><p className="mt-1 text-sm text-graphite-600 dark:text-graphite-400">Offer services customers can discover and pay for on TTFL Store.</p></div><Link href="/vendor/dashboard/services/new" className="inline-flex items-center justify-center gap-2 rounded-card bg-ember-600 px-4 py-2.5 text-sm font-semibold text-white hover:bg-ember-700"><Plus className="h-4 w-4"/>Add service</Link></div>
 <div className="mt-6 rounded-card border border-graphite-200 bg-white p-4 dark:border-graphite-700 dark:bg-graphite-900"><div className="flex items-start gap-3"><span className="grid h-10 w-10 place-items-center rounded-card bg-cloud-100 dark:bg-graphite-800"><Wrench className="h-5 w-5"/></span><div><p className="font-semibold text-graphite-900 dark:text-white">Sell expertise, not just products</p><p className="mt-1 text-sm text-graphite-600 dark:text-graphite-400">Use fixed pricing, starting-from pricing, or quote-required services. Add a service area and optional booking requirement.</p></div></div></div>
 {error&&<p className="mt-4 text-sm font-medium text-ember-600">{error}</p>}
 {loading?<p className="py-12 text-center text-sm text-graphite-500">Loading services…</p>:services.length===0?<div className="mt-6 rounded-card border border-dashed border-graphite-300 p-10 text-center dark:border-graphite-700"><Wrench className="mx-auto h-8 w-8 text-graphite-400"/><h2 className="mt-3 font-semibold text-graphite-900 dark:text-white">No services yet</h2><p className="mt-1 text-sm text-graphite-500">Create your first service listing and start reaching customers.</p><Link href="/vendor/dashboard/services/new" className="mt-4 inline-flex rounded-card bg-ember-600 px-4 py-2 text-sm font-semibold text-white">Create service</Link></div>:<div className="mt-6 grid gap-4 md:grid-cols-2">{services.map(s=><div key={s.id} className="rounded-card border border-graphite-200 bg-white p-5 dark:border-graphite-700 dark:bg-graphite-900"><div className="flex items-start justify-between gap-3"><div><h2 className="font-semibold text-graphite-900 dark:text-white">{s.title}</h2><p className="mt-1 line-clamp-2 text-sm text-graphite-500">{s.description}</p></div><span className="rounded-full bg-cloud-100 px-2.5 py-1 text-xs font-semibold dark:bg-graphite-800">{s.status}</span></div><div className="mt-4 grid gap-2 text-sm text-graphite-600 dark:text-graphite-300"><span className="flex items-center gap-2"><Tag className="h-4 w-4"/>{s.price_type==="QUOTE"?"Quote required":s.price_type==="STARTING_FROM"?`From ₦${Number(s.price??0).toLocaleString()}`:`₦${Number(s.price??0).toLocaleString()}`}</span>{s.location&&<span className="flex items-center gap-2"><MapPin className="h-4 w-4"/>{s.location}</span>}<span className="flex items-center gap-2"><CalendarCheck className="h-4 w-4"/>{s.booking_required?"Booking required":"No booking required"}</span></div></div>)}</div>}
 </div>
}
